import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfCurso = () => {
  const { id } = useParams(); // Captura o ID do curso pela URL
  const [curso, setCurso] = useState(null); // Estado para armazenar as informações do curso
  const [editMode, setEditMode] = useState(false); // Controle do modo de edição

  // Função para buscar as informações do curso
  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    fetchCurso();
  }, [id]);

  // Função para ativar o modo de edição
  const handleEditClick = () => setEditMode(true);

  // Função para cancelar a edição
  const handleCancelClick = () => setEditMode(false);

  // Função para salvar as edições do curso
  const handleSaveClick = async () => {
    if (!curso) return;

    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(curso),
      });

      if (resposta.ok) {
        setEditMode(false);
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Função para atualizar os dados do curso
  const handleChange = (e) => {
    setCurso({ ...curso, [e.target.name]: e.target.value });
  };

  // Função para atualizar os alunos
  const handleAlunoChange = (index, value) => {
    const novosAlunos = [...curso.alunos];
    novosAlunos[index] = value;
    setCurso({ ...curso, alunos: novosAlunos });
  };

  // Função para adicionar um aluno
  const handleAddAluno = () =>
    setCurso({ ...curso, alunos: [...curso.alunos, ""] });

  if (!curso) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistprof">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={handleEditClick}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        {/* Informação do curso */}
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informações do Curso</h4>
          <p>
            <strong>{curso.nome}</strong>
          </p>
          <p>{curso.nivel}</p>
          <p>{curso.periodo}</p>
          <p>{curso.area}</p>
        </div>

        {/* Formulário de edição */}
        <div className="w-50 ps-4">
          <div className="mb-3">
            <label className="fw-bold">Professor</label>
            <div className="input-group">
              <input
                type="text"
                className="form-control"
                name="professor"
                value={curso.professor}
                onChange={handleChange}
                disabled={!editMode}
              />
            </div>
          </div>

          <label className="fw-bold">Alunos</label>
          {curso.alunos.map((aluno, index) => (
            <div key={index} className="input-group mb-2">
              <input
                type="text"
                className="form-control"
                value={aluno}
                onChange={(e) => handleAlunoChange(index, e.target.value)}
                disabled={!editMode}
              />
            </div>
          ))}

          {editMode && (
            <div className="d-flex justify-content-between mt-3">
              <button className="btn btn-danger" onClick={handleCancelClick}>
                Cancelar
              </button>
              <button className="btn btn-primary" onClick={handleAddAluno}>
                Adicionar Aluno
              </button>
              <button className="btn btn-primary" onClick={handleSaveClick}>
                Salvar
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfCurso;
